# ===== FRIDA: ANDROID APP ANALYSIS =====
# Frida lets you hook into running Android/iOS apps
# and modify their behavior in real-time

"""
PREREQUISITES:
  pip install frida-tools
  adb install frida-server (on rooted Android device)
  OR use Objection (which wraps Frida)
"""

# ===== 1. BYPASS ROOT DETECTION =====
# JavaScript hook for Frida:

Java.perform(function() {
    console.log("[*] Bypassing root detection...");

    // Hook common root check methods
    var RootBeer = Java.use('com.scottyab.rootbeer.RootBeer');
    RootBeer.isRooted.implementation = function() {
        console.log("[*] Root check bypassed!");
        return false;
    };

    // Hook File.exists for su binary checks
    var File = Java.use('java.io.File');
    File.exists.implementation = function() {
        var path = this.getAbsolutePath();
        if (path.contains("su") || path.contains("magisk") || path.contains("supersu")) {
            console.log("[*] Blocked file check: " + path);
            return false;
        }
        return this.exists.call(this);
    };

    // Hook Build.TAGS for test-keys
    var Build = Java.use('android.os.Build');
    Build.TAGS.value = "release-keys";  // Override to look like stock
});

// Run: frida -U -f com.target.app -l bypass_root.js

