# ===== 3. HOOK CRYPTOGRAPHIC FUNCTIONS =====
// Capture encryption keys
Java.perform(function() {
    var Cipher = Java.use('javax.crypto.Cipher');
    Cipher.init.overload('int', 'java.security.Key', 'java.security.AlgorithmParameters').implementation = function(mode, key, params) {
        console.log("[*] Cipher initialized with key: " + key.toString());
        return this.init(mode, key, params);
    };

    // Capture AES keys
    var SecretKeySpec = Java.use('javax.crypto.spec.SecretKeySpec');
    SecretKeySpec.$init.overload('[B', 'java.lang.String').implementation = function(keyData, algorithm) {
        console.log("[*] SecretKeySpec created:");
        console.log("    Algorithm: " + algorithm);
        console.log("    Key (hex): " + bytesToHex(keyData));
        return this.$init(keyData, algorithm);
    };
});

function bytesToHex(bytes) {
    var hex = [];
    for (var i = 0; i < bytes.length; i++) {
        hex.push((bytes[i] >>> 4).toString(16));
        hex.push((bytes[i] & 0xF).toString(16));
    }
    return hex.join('');
}

