# ===== 2. BYPASS JAILBREAK DETECTION =====
ObjC.perform(function() {
    console.log("[*] Bypassing iOS jailbreak detection...");

    // Common jailbreak detection methods
    var FileManager = ObjC.classes.NSFileManager;
    var originalMethod = FileManager['- fileExistsAtPath:'];

    // Intercept file checks for jailbreak files
    ObjC.schedule(ObjC.mainQueue, function () {
        var hook = FileManager['- fileExistsAtPath:'];
        var oldImp = hook.implementation;
        hook.implementation = ObjC.implement(hook, function (self, sel, path) {
            var bannedPaths = [
                "/Applications/Cydia.app",
                "/Library/MobileSubstrate/",
                "/bin/bash",
                "/usr/sbin/sshd",
                "/etc/apt",
                "/private/var/lib/apt/"
            ];
            for (var i = 0; i < bannedPaths.length; i++) {
                if (path.toString() === bannedPaths[i]) {
                    console.log("[*] Blocked jailbreak file check: " + path);
                    return false;
                }
            }
            return oldImp(self, sel, path);
        });
    });
});

